const SERVICE_FAQS: Record<string, {q:string; a:string}[]> = {
  'personalized-counselling': [
    {q:'How does ALO counseling differ from free online advice?', a:'Our counselors provide personalized guidance based on your specific academic profile, career goals, and constraints. Unlike generic online advice, we create a customized plan with specific university and course recommendations tailored to you.'},
    {q:'How long does the counseling process take?', a:'The initial consultation is 30 minutes. The complete study plan is typically delivered within 3-5 working days after we receive all your documents. The entire process usually spans 2-4 weeks.'},
    {q:'Can I get counseling for multiple countries?', a:'Yes. Our counselors are experienced with multiple study destinations and can help you compare options across countries to find the best fit for your profile and goals.'},
    {q:'What if I am not sure what to study?', a:'That is exactly when counseling is most valuable. Our counselors use your academic background, interests, and career aspirations to help you identify suitable courses and career paths.'},
    {q:'Is the initial consultation really free?', a:'Yes. The initial consultation is completely free and without obligation. It helps us understand your needs and helps you decide if our services are right for you.'},
  ],
  'university-selection': [
    {q:'How many universities should I apply to?', a:'We typically recommend applying to 3-5 universities: 1 aspirational, 2-3 target, and 1 safe choice. This balances your chances of admission while managing application costs.'},
    {q:'Should I only apply to top-ranked universities?', a:'No. Rankings are one factor among many. Course quality, fit for your profile, career outcomes, location, cost, and scholarship availability are all important considerations. We help you evaluate universities holistically.'},
    {q:'Can you guarantee I will get admitted?', a:'No. We do not guarantee admission as admission decisions are made by universities. However, our data-driven approach and thorough preparation significantly improve your chances by ensuring you apply to universities where you have a strong profile match.'},
    {q:'How do you decide which universities to recommend?', a:'We analyze your academic profile, English test scores, budget, career goals, and preferences against each university admission requirements, scholarship availability, and career outcome data.'},
  ],
  'visa-guidance': [
    {q:'Which countries require a visa interview?', a:'The United States requires a visa interview at the embassy. The UK may require a credibility interview. Other countries like Australia and Canada typically do not require interviews but may request additional evidence.'},
    {q:'What financial evidence do I need for a student visa?', a:'Requirements vary by country, but typically include bank statements showing sufficient funds for tuition and living costs, sponsor income evidence, and sometimes a loan sanction letter. We provide country-specific guidance.'},
    {q:'Can you guarantee my visa will be approved?', a:'No. Visa decisions are made by immigration authorities and are outside our control. However, proper preparation significantly reduces the risk of refusal due to document errors or insufficient evidence.'},
    {q:'What happens if my visa is refused?', a:'If your visa is refused, we help you understand the refusal reasons, assess your options for reapplication, and prepare a stronger application if you choose to reapply.'},
  ],
  'scholarship-guidance': [
    {q:'Are scholarships really available for Bangladeshi students?', a:'Yes. There are government scholarships (like Chevening, Australia Awards), university-specific scholarships, and external scholarships. Eligibility varies, but many are open to international students including Bangladeshis.'},
    {q:'What are my chances of getting a scholarship?', a:'Scholarship chances depend on your academic profile, the type of scholarship, and competition. Merit-based scholarships are highly competitive. We help you identify scholarships where you have the strongest match.'},
    {q:'When should I start applying for scholarships?', a:'Scholarship deadlines are often 6-12 months before the course start date. We recommend starting your scholarship research at least 10-12 months before your intended intake.'},
    {q:'Do I need a separate scholarship application?', a:'It depends. Some scholarships are automatically considered with your admission application. Others require a separate application with additional essays or documents. We help you understand the process for each scholarship.'},
  ],
};

async function main() {
  console.log('Seeding services...');

  // Delete existing
  await db.serviceFaq.deleteMany({});
  const deleted = await db.service.deleteMany({});
  console.log(`Deleted ${deleted.count} existing services`);

  // Create new services
  for (const s of SERVICES) {
    try {
      const service = await db.service.create({
        data: {
          title: s.title,
          slug: s.slug,
          icon: s.icon,
          description: s.description,
          longDescription: s.longDescription,
          whatItIs: s.whatItIs,
          whyStudentsNeed: s.whyStudentsNeed,
          whoItIsFor: s.whoItIsFor,
          whatALOdoes: s.whatALOdoes,
          stepByStep: s.stepByStep,
          documentsNeeded: s.documentsNeeded,
          timeline: s.timeline,
          whatStudentsGet: s.whatStudentsGet,
          whatALOdoesNot: s.whatALOdoesNot,
          commonMistakes: s.commonMistakes,
          fees: s.fees,
          ctaLabel: s.ctaLabel,
          sortOrder: s.sortOrder,
          status: 'ACTIVE',
          verificationStatus: 'NEEDS_REVIEW',
          lastVerifiedAt: new Date(),
          metaTitle: `${s.title} - ALO Education`,
          metaDescription: s.description,
        },
      });
      console.log(`  Created: ${s.slug}`);

      // Create FAQs
      const faqs = SERVICE_FAQS[s.slug];
      if (faqs) {
        for (let i = 0; i < faqs.length; i++) {
          await db.serviceFaq.create({
            data: {
              serviceId: service.id,
              question: faqs[i].q,
              answer: faqs[i].a,
              sortOrder: i,
              status: 'ACTIVE',
            },
          });
        }
        console.log(`    + ${faqs.length} FAQs`);
      }
    } catch (e: any) {
      console.error(`  Error creating ${s.slug}: ${e.message}`);
    }
  }

  const finalCount = await db.service.count({ where: { status: 'ACTIVE' } });
  const faqCount = await db.serviceFaq.count();
  console.log(`\nDone! ${finalCount} services, ${faqCount} FAQs`);
}

main()
  .catch(console.error)
  .finally(() => db.$disconnect());
